cat > $J/ClaimStatus.java <<'EOF'
package net.officefloor.hq.app.claim;

/** A claim's status. It starts DRAFT; DRAFT → OPEN → SETTLED; DRAFT or OPEN → VOID. SETTLED and VOID are final. */
public enum ClaimStatus {
    DRAFT, OPEN, SETTLED, VOID;

    /** Whether a claim in this status may move to {@code to}. */
    public boolean canBecome(ClaimStatus to) {
        return switch (to) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN;
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status counts toward claimed, due-total and every total. */
    public boolean counts() {
        return this == OPEN || this == SETTLED;
    }
}
EOF
cat > $J/InvalidClaimStatusException.java <<'EOF'
package net.officefloor.hq.app.claim;

/** The claim's status cannot make the requested change (SETTLED and VOID are final); nothing is changed. */
public class InvalidClaimStatusException extends Exception {
    public InvalidClaimStatusException(String message) {
        super(message);
    }
}
EOF
cat > $J/HandleInvalidClaimStatus.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidClaimStatus {
    public void handle(@Parameter InvalidClaimStatusException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
EOF
cat > src/main/resources/officefloor/escalation/net.officefloor.hq.app.claim.InvalidClaimStatusException.yml <<'EOF'
handle:
  class: net.officefloor.hq.app.claim.HandleInvalidClaimStatus
EOF
cat > $J/ClaimTransition.java <<'EOF'
package net.officefloor.hq.app.claim;

/** Moves a claim to a new status, refusing a change its current status does not allow. */
final class ClaimTransition {
    private ClaimTransition() {
    }

    static void to(Claim claim, ClaimStatus to) throws InvalidClaimStatusException {
        if (!claim.getStatus().canBecome(to)) {
            throw new InvalidClaimStatusException(
                    "A " + claim.getStatus() + " claim cannot become " + to + ".");
        }
        claim.setStatus(to);
    }
}
EOF
