package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.HttpHeaderParameter;

/** Records CLAIM_${Ev} once the claim is saved; the signed-in user arrives as X-User. */
public class AuditClaim${Evc} {
    public void audit(@Val Claim claim, @HttpHeaderParameter("X-User") String user,
            PersonRepository people, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_${Ev}", claim, user, people));
    }
}
EOF
mkdir -p "src/main/resources/officefloor/rest/api/sheets/{sheetId}/claims/{claimId}"
cat > "src/main/resources/officefloor/rest/api/sheets/{sheetId}/claims/{claimId}/${word}.POST.yml" <<EOF
# Move a claim to ${St}. A change its status does not allow is refused (409) and writes nothing.
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.${Verb}Claim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
# Record the change only once it is saved, so a refused change writes no audit line.
audit:
  class: net.officefloor.hq.app.claim.AuditClaim${Evc}
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
EOF
done
